require 'sablon/spreadsheet/cell_reference'
require 'sablon/spreadsheet/formula'

module Sablon
  module Spreadsheet
    # Maps positions of a worksheet template to the positions of the
    # rendered worksheet. Rows and cells generated by blocks remember the
    # template position they were copied from and the block iterations that
    # produced them (tokens). References are mapped using these rules:
    #
    # * A relative reference from a cell generated by a block iteration
    #   resolves to the cells generated by the same iteration.
    # * Column relative references from a column loop iteration to cells of
    #   another column loop resolve to the iteration with the same index.
    # * Other references cover all generated copies of the referenced
    #   cells, i.e. SUM(D6) in a row below a loop repeating row 6 becomes
    #   SUM(D6:D8). Absolute references from within the loop repeating the
    #   cell point to the first copy instead.
    # * References are replaced with #REF! if no copies exist.
    # * Whole column references (A:C) are not changed.
    class PositionMap
      EMPTY = [].freeze

      # +block+ identifies the template block, +copy+ the block iteration
      # and +index+ is the position of the iteration within its loop.
      # Tokens are ordered from the outermost to the innermost block.
      Token = Struct.new(:block, :copy, :index)

      # A rendered position. Rendered rows store the column axis of their
      # cells if a column loop was used in the row.
      Entry = Struct.new(:pos, :tokens, :columns)

      # One dimensional mapping of the template positions within a region
      # to rendered positions. Positions before the region are unchanged and
      # positions after it are moved by +delta+.
      class Axis
        attr_reader :first, :last, :delta

        def initialize(first, last, delta, entries)
          @first = first
          @last = last
          @delta = delta
          @entries = entries
          @groups = {}
        end

        def candidates(pos)
          return [Entry.new(pos, EMPTY, nil)] if @first.nil? || pos < @first
          return [Entry.new(pos + @delta, EMPTY, nil)] if pos > @last
          @entries.fetch(pos, EMPTY)
        end

        # Returns the entries of a template position generated by the block
        # iterations of the context. All copies of a template position are
        # nested in the same blocks and the blocks shared with the context
        # are always the outermost ones, the entries are therefore indexed
        # by the copies of those blocks.
        def matching(pos, context)
          entries = candidates(pos)
          return entries if entries.empty? || context.empty?
          chain = entries.first.tokens
          key = []
          chain.each do |token|
            own = context.detect { |ctx| ctx.block == token.block }
            break unless own
            key << own.copy
          end
          return entries if key.empty?
          (@groups[[pos, key.length]] ||= entries.group_by do |entry|
            entry.tokens.first(key.length).map(&:copy)
          end).fetch(key, EMPTY)
        end

        # Yields the rendered positions of the template positions between
        # +from+ and +to+. Positions outside of the region are yielded as
        # spans: (nil, rendered_from, rendered_to), positions inside of it as
        # groups of matching entries: (entries, nil, nil).
        def each_match(from, to, context = EMPTY)
          from, to = to, from if from > to
          if @first.nil?
            yield nil, from, to
            return
          end
          yield nil, from, [to, @first - 1].min if from < @first
          ([from, @first].max..[to, @last].min).each do |pos|
            group = matching(pos, context)
            yield group, nil, nil unless group.empty?
          end
          yield nil, [from, @last + 1].max + @delta, to + @delta if to > @last
        end

        # Yields each rendered entry for the template positions between
        # +from+ and +to+, see #each_match for the arguments.
        def each_candidate(from, to)
          each_match(from, to) do |group, span_from, span_to|
            next yield(nil, span_from, span_to) unless group
            group.each { |entry| yield entry, entry.pos, entry.pos }
          end
        end

        def region?(from, to)
          !@first.nil? && from <= @last && to >= @first
        end

        # true if any position between +from+ and +to+ has been moved,
        # copied or removed.
        def changes?(from, to)
          return false unless changed?
          region?(from, to) || (@delta != 0 && to > @last)
        end

        def changed?
          return @changed if defined?(@changed)
          @changed = !@first.nil? && (@delta != 0 || (@first..@last).any? { |pos| moved?(pos) })
        end

        private

        def moved?(pos)
          entries = @entries.fetch(pos, EMPTY)
          entries.length != 1 || entries.first.pos != pos
        end
      end

      IDENTITY_AXIS = Axis.new(nil, nil, 0, {})

      def self.identity
        new(IDENTITY_AXIS)
      end

      attr_reader :rows

      def initialize(rows)
        @rows = rows
        @group_extents = {}.compare_by_identity
        @column_extents = {}.compare_by_identity
      end

      def identity?
        @rows.first.nil?
      end

      # Returns the new text of a reference or REF_ERROR if the referenced
      # cells no longer exist. +context+ is a pair of row and cell tokens of
      # the cell containing the reference. The +mode+ defines how single
      # cells with multiple copies are mapped:
      #
      # * :formula - expands to all copies unless the formula is part of
      #   the blocks repeating the cell
      # * :area - always expands to all copies (cell ranges like "sqref")
      # * :first - uses the first copy (formulas of conditional formatting
      #   rules and data validations, which are relative to the first cell)
      def map_reference(ref, context = nil, mode = :formula)
        row_ctx, cell_ctx = context || [EMPTY, EMPTY]
        case ref.kind
        when :cell
          map_cell(ref, row_ctx, cell_ctx, mode)
        when :range
          map_range(ref, row_ctx, cell_ctx)
        when :rows
          map_rows(ref, row_ctx)
        end
      end

      # Returns the rendered [row, column] of the first copy of a template
      # cell or nil if it has been removed.
      def first(row, col, row_ctx = EMPTY, cell_ctx = EMPTY)
        @rows.matching(row, row_ctx).each do |entry|
          new_col = first_column(entry.columns, col, cell_ctx)
          return [entry.pos, new_col] if new_col
        end
        nil
      end

      # Like #first but removed positions collapse onto the next rendered
      # row. Used to position objects anchored to cells.
      def point(row, col)
        first(row, col) || [collapse_row(row), col]
      end

      # Returns [min_row, min_col, max_row, max_col] covering all rendered
      # copies of the template range or nil if there are none.
      def extent(row1, col1, row2, col2, row_ctx = EMPTY, cell_ctx = EMPTY)
        box = nil
        @rows.each_match(row1, row2, row_ctx) do |group, from, to|
          if group.nil?
            box = merge(box, [from, [col1, col2].min, to, [col1, col2].max])
          elsif (rows = plain_extent(group))
            box = merge(box, [rows[0], [col1, col2].min, rows[1], [col1, col2].max])
          elsif cell_ctx.empty?
            cached = (@column_extents[group] ||= {})
            key = [col1, col2]
            cached[key] = group_extent(group, col1, col2, cell_ctx) unless cached.key?(key)
            box = merge(box, cached[key]) if cached[key]
          else
            other = group_extent(group, col1, col2, cell_ctx)
            box = merge(box, other) if other
          end
        end
        box
      end

      # Template rows between +from+ and +to+ that contain a column loop
      # changing the columns between +col1+ and +col2+.
      def column_changes?(from, to, col1, col2)
        found = false
        @rows.each_candidate(from, to) do |entry, _from, _to|
          found ||= entry && entry.columns && entry.columns.changes?(col1, col2)
        end
        found
      end

      private

      # A single cell repeated by blocks the formula is not part of expands
      # to all of its copies (i.e. "SUM(D6)" in a row below a loop), else
      # the first matching copy is used.
      def map_cell(ref, row_ctx, cell_ctx, mode)
        row_bind = bind(row_ctx, ref.abs_row1)
        cell_bind = bind(cell_ctx, ref.abs_col1)
        box = extent(ref.row1, ref.col1, ref.row1, ref.col1, row_bind, cell_bind)
        return Formula::REF_ERROR unless box
        if box[0] != box[2] || box[1] != box[3]
          expand = mode == :area || (mode == :formula && !repeated_with?(ref.row1, ref.col1, row_ctx, cell_ctx))
          return format_box(box, ref.abs_row1, ref.abs_col1, ref.abs_row1, ref.abs_col1, true) if expand
        end
        pos = first(ref.row1, ref.col1, row_bind, cell_bind)
        return Formula::REF_ERROR unless CellReference.valid?(pos[0], pos[1])
        CellReference.format(pos[0], pos[1], ref.abs_row1, ref.abs_col1)
      end

      # true if the context is part of all blocks repeating the template cell
      def repeated_with?(row, col, row_ctx, cell_ctx)
        entry = @rows.candidates(row).first
        return true unless entry
        return false unless entry.tokens.all? { |token| row_ctx.any? { |ctx| ctx.block == token.block } }
        cell = entry.columns && entry.columns.candidates(col).first
        cell.nil? || cell.tokens.all? { |token| cell_ctx.any? { |ctx| ctx.block == token.block } }
      end

      # The start corner is mapped using the bindings of the first part of
      # the range and the end corner using the bindings of the second part.
      # This allows ranges like $D$4:D4 to grow with each iteration.
      def map_range(ref, row_ctx, cell_ctx)
        start_box = extent(ref.row1, ref.col1, ref.row2, ref.col2,
                           bind(row_ctx, ref.abs_row1), bind(cell_ctx, ref.abs_col1))
        end_box = if ref.abs_row1 == ref.abs_row2 && ref.abs_col1 == ref.abs_col2
                    start_box
                  else
                    extent(ref.row1, ref.col1, ref.row2, ref.col2,
                           bind(row_ctx, ref.abs_row2), bind(cell_ctx, ref.abs_col2))
                  end
        start_box ||= end_box
        end_box ||= start_box
        return Formula::REF_ERROR unless start_box
        box = [start_box[0], start_box[1], end_box[2], end_box[3]]
        box[0], box[2] = box[2], box[0] if box[0] > box[2]
        box[1], box[3] = box[3], box[1] if box[1] > box[3]
        format_box(box, ref.abs_row1, ref.abs_col1, ref.abs_row2, ref.abs_col2, true)
      end

      def map_rows(ref, row_ctx)
        start_rows = row_extent(ref.row1, ref.row2, bind(row_ctx, ref.abs_row1))
        end_rows = row_extent(ref.row1, ref.row2, bind(row_ctx, ref.abs_row2))
        start_rows ||= end_rows
        end_rows ||= start_rows
        return Formula::REF_ERROR unless start_rows
        from, to = [start_rows[0], end_rows[1]].minmax
        return Formula::REF_ERROR unless CellReference.valid_row?(from) && CellReference.valid_row?(to)
        "#{'$' if ref.abs_row1}#{from}:#{'$' if ref.abs_row2}#{to}"
      end

      def row_extent(from, to, row_ctx)
        min = max = nil
        @rows.each_match(from, to, row_ctx) do |group, span_from, span_to|
          span_from, span_to = group.first.pos, group.last.pos if group
          min = span_from if min.nil? || span_from < min
          max = span_to if max.nil? || span_to > max
        end
        min && [min, max]
      end

      # Returns the [min, max] rows of a group of entries whose cells use
      # the template columns. Returns nil if the group contains rows with
      # column loops.
      def plain_extent(group)
        return @group_extents[group] if @group_extents.key?(group)
        @group_extents[group] = if group.any?(&:columns)
                                  nil
                                else
                                  group.map(&:pos).minmax
                                end
      end

      def group_extent(group, col1, col2, cell_ctx)
        box = nil
        group.each do |entry|
          cols = column_extent(entry.columns, col1, col2, cell_ctx)
          box = merge(box, [entry.pos, cols[0], entry.pos, cols[1]]) if cols
        end
        box
      end

      # Positions moved beyond the limits of the sheet result in #REF!
      def format_box(box, abs_row1, abs_col1, abs_row2, abs_col2, range = false)
        return Formula::REF_ERROR unless CellReference.valid?(box[0], box[1]) && CellReference.valid?(box[2], box[3])
        start = CellReference.format(box[0], box[1], abs_row1, abs_col1)
        return start if !range && box[0] == box[2] && box[1] == box[3]
        start + ':' + CellReference.format(box[2], box[3], abs_row2, abs_col2)
      end

      # absolute parts of a reference are not bound to block iterations
      def bind(tokens, absolute)
        absolute ? EMPTY : tokens
      end

      def first_column(axis, col, cell_ctx)
        return col if axis.nil?
        axis.candidates(col).each do |entry|
          return entry.pos if cell_match?(entry.tokens, cell_ctx)
        end
        nil
      end

      def column_extent(axis, col1, col2, cell_ctx)
        return [col1, col2].minmax if axis.nil?
        min = max = nil
        axis.each_candidate(col1, col2) do |entry, from, to|
          next if entry && !cell_match?(entry.tokens, cell_ctx)
          min = from if min.nil? || from < min
          max = to if max.nil? || to > max
        end
        min && [min, max]
      end

      def collapse_row(row)
        return row if @rows.first.nil? || row < @rows.first
        (row..@rows.last).each do |pos|
          entries = @rows.candidates(pos)
          return entries.first.pos unless entries.empty?
        end
        @rows.last + 1 + @rows.delta
      end

      def merge(box, other)
        return other unless box
        [[box[0], other[0]].min, [box[1], other[1]].min,
         [box[2], other[2]].max, [box[3], other[3]].max]
      end

      def cell_match?(tokens, context)
        tokens.each_with_index.all? do |token, depth|
          own = context.detect { |ctx| ctx.block == token.block }
          if own
            own.copy == token.copy
          elsif context[depth]
            context[depth].index == token.index
          else
            true
          end
        end
      end
    end
  end
end
